// Booking confirmation shown large: after submitting the booking, the chosen service, doctor,
// date and time appear big on the left, with a delivery status indicator and a note on the right
// (booking page, after the form). Swiss grid, formal tone, still motion — no animation.
export type BookingConfirmationStatusProps = {
  title: string;
  service: string;
  doctor: string;
  date: string;
  time: string;
  statusNote: string;
  statusValue: string;
  afterNote: string;
};

export default function BookingConfirmationStatus({
  title,
  service,
  doctor,
  date,
  time,
  statusNote,
  statusValue,
  afterNote,
}: BookingConfirmationStatusProps) {
  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>

        <div className="mt-8 grid grid-cols-1 gap-px border border-border bg-border md:grid-cols-3">
          <div className="bg-card p-6 min-w-0 md:col-span-2 md:p-10">
            <dl className="grid grid-cols-1 gap-8 sm:grid-cols-2">
              <div className="min-w-0 sm:col-span-2">
                <dt className="text-small font-medium uppercase tracking-wide text-muted-foreground">Услуга</dt>
                <dd className="mt-2 font-display text-h3 font-bold text-balance wrap-break-word">{service}</dd>
              </div>
              <div className="min-w-0 sm:col-span-2">
                <dt className="text-small font-medium uppercase tracking-wide text-muted-foreground">Врач</dt>
                <dd className="mt-2 font-display text-h3 font-bold text-balance wrap-break-word">{doctor}</dd>
              </div>
              <div className="min-w-0">
                <dt className="text-small font-medium uppercase tracking-wide text-muted-foreground">Дата</dt>
                <dd className="mt-2 font-display text-h3 font-bold text-balance wrap-break-word">{date}</dd>
              </div>
              <div className="min-w-0">
                <dt className="text-small font-medium uppercase tracking-wide text-muted-foreground">Время</dt>
                <dd className="mt-2 font-display text-h3 font-bold text-balance wrap-break-word">{time}</dd>
              </div>
            </dl>
          </div>

          <div className="bg-muted p-6 min-w-0 md:p-10">
            <p className="text-lead text-balance wrap-break-word">{statusNote}</p>
            <div className="mt-6 flex items-center gap-3">
